public Map addTranslations()
{
    Map ret = new Map(Types::String, Types::String);

    ret.insert('CartOverview', "@MobileWMS:UnplannedCartMove");
    ret.insert('CartContent', "@MobileWMS:CartContents");
    ret.insert('AddItemToCart', "@MobileWMS:Movetoorfromcart");
    ret.insert('CartAdd', "@MobileWMS:NewCart");
    ret.insert('CartUnload', "@MobileWMS:UnloadCart");
    ret.insert('CartChangeNote', "@SYS71808");
    ret.insert('AttachToCart', "@MobileWMS:AttachToCart");
    ret.insert('attachListToCart',"@MobileWMS:AttachToCart");
    ret.insert('detachListFromCart', "@SYS73324");
    ret.insert('Switch', "@SYS40412");

    return ret;
}

[TFMReferenceDataMethodAttribute('CartOverview;AddNewCart')]
public TFMReferenceDataConfiguration CartOverviewFilter()
{
    TFMReferenceDataConfiguration   refData = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorList    regCollectorList = new TFMRegistrationCollectorList(5,MobConstants::Warehouse(),"@SYS6437","@SYS6437","@SYS6437");

    regCollectorList.parmDataTable(methodStr(TFMGetReferenceData,WarehouseFilterList));
    regCollectorList.parmDataKeyColumn(extendedtypestr(InventLocationId));
    regCollectorList.parmDataDisplayColumn(extendedtypestr(Name));

    refData.addCollector(regCollectorList);

    return refData;
}

[TFMReferenceDataMethodAttribute('CartChangeNote;CartSwitchMode;CartUnload')]
