public TFMPages pages()
{
    TFMPages							            ret		= MobPageHelper::getPagesFromClass(this);
    TFMPage								            cartOverViewPage	= ret.getPage(MobConstants::CartOverview());
    TFMPageLookupConfiguration			            lookupListConfig = cartOverViewPage.getConfiguration();
    TFMPageOrderListConfiguration		            Listconfig;
    TFMPageOrderList					            listPage = new TFMPageOrderList();
    TFMPageLookupConfiguration			            lookupConf;
    TFMPageUnplannedItemRegistration	            page;
    TFMPageUnplannedItemRegistrationConfiguration   UnplPageConfig;
    TFMDataSourceBlockLockOrderList		dsbOrderList = new TFMDataSourceBlockLockOrderList();//Containing IC4        
    TFMMenuItemStateConfiguration       menuItem = TFMMenuItemStateConfiguration::Construct('CartSwitchMode',1);
    cartOverViewPage.addAction('AddNewCart',1,5).getPageActionSetup().parmVisibleWhenNoData(true);

    cartOverViewPage.addAction('CartUnload',2);
    cartOverViewPage.addAction('CartChangeNote',3);        
    cartOverViewPage.addAdhocAction(methodStr(MobDocUnplannedCartMove,postAttachListToCart ),4,5,'CartContent');
    cartOverViewPage.addAdhocAction(methodStr(MobDocUnplannedCartMove,postDetachListFromCart ),5,5);        
    cartOverViewPage.setListId(classStr(TFMListLookupJournalHeader));
    cartOverViewPage.parmDescription("@MobileWMS:TheCartOverviewgivesyouanovervie");
    lookupListConfig = cartOverViewPage.getConfiguration();

    lookupListConfig.parmNavigateTo(methodStr(MobDocUnplannedCartMove,CartContent)); 

    listPage.parmId('CartContent');
    listPage.parmAvailableForMenuPages(false);
    listPage.parmFilter(methodStr(MobDocUnplannedCartMove,CartContentFilter));
    listPage.parmIcon('CartIcon');
    listPage.parmTitle('@{CartContent}');

    dsbOrderList.parmUseOrderLocking(false);
    listPage.addDataSourceBlock(dsbOrderList);

    listConfig = listPage.getConfiguration();
    listConfig.parmNavigateTo('AddItemToCart');
    Listconfig.parmListId(classStr(MobListLookupCartContent));

    menuItem.parmTitle('{PickMode}');
    listPage.addActionClass(menuItem,2);
    listPage.addAction('CartUnload',2);
    ret.addPage(listPage);

    page = ret.getPage('AddNewCart');
    page.parmAvailableForMenuPages(false);
    page = ret.getPage('AddItemToCart');
    page.parmAvailableForMenuPages(false);
    UnplPageConfig = page.getConfiguration();
    UnplPageConfig.parmClose(true);
    page = ret.getPage('CartChangeNote');
    page.parmAvailableForMenuPages(false);
    page = ret.getPage('CartSwitchMode');
    page.parmAvailableForMenuPages(false);
    UnplPageConfig = page.getConfiguration();
    UnplPageConfig.parmClose(true);
    page = ret.getPage('CartUnload');
    page.parmAvailableForMenuPages(false);

    ret.removePage('attachListToCart');
    ret.removePage('detachListFromCart');
    return ret;
}

    public void CartContent()
    {
        MobBackendId                backendId;
        TFMXMLFormat				xmlFormat;



        InventSum                   inventSum;
        InventDim                   inventDimForInventSum;
        InventLocationId            inventLocationId;
        WmsLocationId               wmsLocationId;
        WMSLocation                 WMSLocation;        
        MapEnumerator				mEnum;

        Query                       q = new Query();
        QueryRun                    qr;
        QueryBuildDataSource        queryBuildDataSource;
        int							i = 1;
        XmlElement					ordersElement;
        InventTable					inventTable;
        TFMRequestGetOrdersElement	cartRequest = request as TFMRequestGetOrdersElement;
        MobCartID					cartID = cartRequest.parmFilters().getFieldValue(extendedTypeStr(MobCartID));

        ItemId						foundItem;
        WHSLicensePlateId			lpId;
        InventDim					iDim;
        Set							LPsShown = new Set(Types::String);
		MobCarts					cart	=	MobCarts::Find(cartID);
        Map							cartContent;
        MobCartType					cartType;

        inventLocationId	= cart.InventLocationId;
        wmsLocationId		= cart.WMSLocationId;


        if (lockCarts && MobReservedCarts::IsCartReserved(cart.CartID, reservationLevel != MobCartReservationLevel::User ? request.parmdeviceID() : '', reservationLevel != MobCartReservationLevel::Device ? curUserId() : ''))
        {
            throw error(MobReservedCarts::reserveInfo(cart.CartID));
        }
        cartType = MobCartType::FindCartTypeSubClass(cartRequest.parmFilters().parmScannedValue() ? cartRequest.parmFilters().parmScannedValue() : cart.ReferenceId);
		//Test if scan is a picklist

        if (cartType != null && cartRequest.parmFilters().parmScannedValue() && !MobCarts::FindByReference(cartRequest.parmFilters().parmScannedValue()))
        {
            ttsbegin;
            cart.selectForUpdate(true);
            cart.ReferenceId = cartRequest.parmFilters().parmScannedValue();
            cart.ReferenceCategory = cartType.typeOfCart();
            cart.update();
            ttscommit;
        }
		if (cartType == null)
        {
            cartType = MobCartType::FindCartTypeSubClass(cart.ReferenceId);
        }

        resultXml   = new XmlDocument();
        ordersElement = resultXml.appendChild(resultXml.createElement(MobConstants::Orders()));

        if (cartRequest.parmFilters().parmScannedValue() && cart.PickMode)
        {
            foundItem = MobHelper::string2ItemID(cartRequest.parmFilters().parmScannedValue(),iDim);
            inventTable = InventTable::Find(foundItem);
            if (inventTable || WHSLicensePlate::exist(cartRequest.parmFilters().parmScannedValue()))
            {
                if (cartType != null)
                {
					if (cartType.scannedItemBackendOverride(foundItem,cartID,resultXml))
                    {
                        return;
                    }
                }
				//Put it in
                backendId = tableStr(inventSum) + '/' + fieldStr(inventSum,RecId) + '/0/';

                // Add the necessary steps for the quarantine order
                xmlFormat = TFMXMLFormat::constructFromBackendID(backendId);

                inventSum.InventLocationId = inventLocationId;

                xmlFormat.initFromCommon(resultXml,inventSum,i);
                xmlFormat.parmPageID('CartContent');

                xmlFormat.addField(MobConstants::ScannedValue(),cartRequest.parmFilters().parmScannedValue());
                xmlFormat.addField(extendedTypeStr(ItemId),cartRequest.parmFilters().parmScannedValue());
                xmlFormat.run();
                return;
            }
        }

        queryBuildDataSource = q.addDataSource(tableNum(WMSLocation));
        queryBuildDataSource.addRange(fieldnum(WMSLocation,WMSLocationId)).value(wmsLocationId);
        queryBuildDataSource.addRange(fieldnum(WMSLocation,InventLocationId)).value(inventLocationId);
		qr = new QueryRun(q);

        while (qr.next())
        {
            WMSLocation = qr.get(tableNum(WMSLocation));
            // Find the information

            cartContent = MobDocUnplannedCartMove::locationContent(WMSLocation);
            mEnum = cartContent.getEnumerator();

            if (cartRequest.parmFilters().parmScannedValue() && !cart.PickMode)
            {
                foundItem = MobHelper::string2ItemID(cartRequest.parmFilters().parmScannedValue(),iDim);
                if (!InventTable::exist(foundItem) && WHSLicensePlate::exist(cartRequest.parmFilters().parmScannedValue()))
                {
                    lpId = cartRequest.parmFilters().parmScannedValue();
                }
            }

			while (mEnum.moveNext())
            {

                inventSum = mEnum.currentValue();

				if (foundItem && foundItem != inventSum.ItemId)
                {
                    continue;
                }
				else if (foundItem)
                {
                    inventDimForInventSum = inventSum.inventDim();
                    if ((iDim.InventColorId != inventDimForInventSum.InventColorId ||
                        iDim.InventSizeId != inventDimForInventSum.InventSizeId ||
                        iDim.InventStyleId != inventDimForInventSum.InventStyleId) && iDim)
                    {
                        continue;
                    }
                }

                if(!inventDimForInventSum)
                {
                    inventDimForInventSum = inventSum.inventDim();
                }

                if (inventDimForInventSum.LicensePlateId && inventDimForInventSum.LicensePlateId != cart.WHSLicensePlateId)
                {
                    if (((!LPsShown.in(inventDimForInventSum.LicensePlateId)) && !lpId) || ((lpId && !LPsShown.in(inventDimForInventSum.LicensePlateId)) && inventDimForInventSum.LicensePlateId == lpID))
                    {
                        xmlFormat = TFMXMLFormat::constructFromBackendID(tableStr(WHSLicensePlate) + '/' + fieldStr(WHSLicensePlate,LicensePlateId) + '/' +inventDimForInventSum.LicensePlateId + '/CartContent');
                        xmlFormat.initFromCommon(resultXml,WHSLicensePlate::find(inventDimForInventSum.LicensePlateId),i);
                        xmlFormat.parmPageID('CartContent');
                        xmlFormat.run();
                        i++;
                        LPsShown.add(inventDimForInventSum.LicensePlateId);
                    }

                    continue;
                }

				if (lpId)
                {
                    continue;
                }
				if (!cart.ReferenceId)
                {
					xmlFormat = TFMXMLFormat::constructFromBackendID(mEnum.currentKey());
					inventSum.inventLocationId = WMSLocation.inventLocationId;
					xmlFormat.initFromCommon(resultXml,inventSum,i);
                    xmlFormat.parmPageID('CartContent');
					xmlFormat.run();
                    i++;
                }


            }
			if (cart.ReferenceId && cartType != null)
            {
                cartType.postProcess(cartContent,cartID,resultXml);
            }
			if (i==1)
            {
                MobReservedCarts::unreserveCart(cartID);
            }
        }
    }

    public static Map locationContent(WMSLocation _wmsLocation, ItemId _itemId = '')
    {
        InventDim                   inventDimCriteria;
        InventDimParm               inventDimParm;
        InventSum                   inventSum;
        InventDim                   inventDim;
        MobBackendId                backendId;
        Map							returnMap = new Map(Types::String, Types::Record);
		inventDimCriteria.clear();
        inventDimCriteria.InventLocationId = _wmsLocation.inventLocationId;
        inventDimCriteria.InventSiteId     = InventLocation::find(_wmsLocation.inventLocationId).InventSiteId;
        inventDimCriteria.wMSLocationId    = _wmsLocation.wmsLocationId;
        inventDimParm.InventLocationIdFlag = NoYes::Yes;
        inventDimParm.InventSiteIdFlag     = NoYes::Yes;
        inventDimParm.WMSLocationIdFlag    = NoYes::Yes;

        // Sum items pr (warehouse) location
        while #InventDimSelect(inventDim, inventDimCriteria ,inventDimParm, forcePlaceholders TableId from,SerialIdIdx,inventDim.WMSLocationId)
            join #InventSumQtyFields from inventSum
            index hint DimIdIdx
            // Summarized (Batchnumber and Serialnumber)
            group by inventSum.ItemId,
                     inventDim.InventSiteId, inventDim.InventLocationId,
                     inventDim.WMSLocationId,
                     inventDim.configId, inventDim.InventColorId, inventDim.InventSizeId, inventDim.InventStyleId
                     , inventDim.inventBatchId, inventDim.inventSerialId, InventSum.RecId, InventSum.InventDimId
                    #if.isAx6
        ,inventDim.wMSPalletId
                     #endif
        where InventDim.InventDimId == inventSum.InventDimId && (inventSum.ItemId == _itemId || !_itemId)
        {
            if (inventSum.PhysicalInvent != 0)
            {
                backendId = tableStr(inventSum) + '/' + fieldStr(inventSum,RecId) + '/' + int642Str(inventSum.recID);//#PickProdOrderPrefix + prodJournalTable.JournalId;

                returnMap.insert(backendid, InventSum);
            }
        }
        return returnMap;
    }

private InventSum getInventSum(MobBackendId _backendId)
{
    InventSum iSum;
    RefRecId  RecId = str2Int64(subStr(_backEndId,17,100));

    select firstonly iSum where iSum.recId == RecId;

    return iSum;
}

    [TFMCollectorMap(classStr(TFMGetRegistrationConfiguration), 'AddItemToCart')]
	public Map AddOrMoveItem()
    {
        Map									returnMap;
        Map									qtyStepMap;
        int									decimalPrecision;
        Map									replaceLabels = new Map(Types::String, Types::String);
        SysDictType							dictType;
        int									add = 10;
        InventDimParm						parm,inventDimParm;
        TFMRequestElement					context = request.parmContextValues();
        MobBackendId						backend = context.getFieldValue(MobConstants::BackendId());
        MobCarts							cart = MobCarts::Find(context.getFieldValue(extendedTypeStr(MobCartID)));
        MobCartType							cartType = MobCartType::FindCartTypeSubClass(cart.ReferenceId);
        boolean								isAddItem = strScan(backend, tableStr(inventSum) + '/' + fieldStr(inventSum,RecId) + '/0',1,100);
        InventSum							iSum = this.getInventSum(backend);
        TFMRequestItemAndDimensionElement	cartRequest = request as TFMRequestItemAndDimensionElement;
        ItemId								itemId = isAddItem ? cartRequest.parmItemId() : iSum.ItemId;
        InventDim							iDim = isAddItem ? cartRequest.parmInventDim() : iSum.inventDim();
        NoYes								isLPItem;
        TFMRegistrationCollectorInformation infoCol;
        TFMRegistrationCollector			regCol;

		if (strScan(backend,tableStr(WHSLicensePlate) + '/' + fieldStr(WHSLicensePlate,licensePlateId),1,100))
        {
            returnMap = new Map(Types::String, Types::Class);
            regCol = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WMSLocationId));
            regCol.parmHeader(regCol.parmHeader() + '(' + "@SYS8828" + ')');
            regCol.parmOptional(false);
            returnMap.insert(regCol.parmName(),regCol.getMap());
            return returnMap;
        }

		if (cartType!= null)
        {
            returnMap = cartType.AddorRemoveItemPromptOverride(cartRequest);
			if (returnMap != null)
            {
                return returnMap;
            }
        }

        if (WHSLicensePlate::exist(cartRequest.parmRawItemId()))
        {
            returnMap = new Map(Types::String, Types::Class);
            infoCol = new TFMRegistrationCollectorInformation(1,'info',strFmt("@SYS76498", "@WAX67", cartRequest.parmRawItemId()),strFmt("@SYS76498", "@WAX67", cartRequest.parmRawItemId()),MobInventDimHelper::LpContentHtml(cartRequest.parmRawItemId()));//'You are about to add License Plate ' + cartRequest.parmRawItemId());
            returnMap.insert(infoCol.parmName(),infoCol.getMap());
            return returnMap;
		}
        parm =  InventDimParm::activeDimFlag(InventDimGroupSetup::newInventTable(InventTable::find(itemId)));
        isLPItem = parm.LicensePlateFlag;
        inventDimParm.initFromInventDim(iDim);
        parm = InventDimParm::xorParms(inventDimParm,parm);
        parm.InventSiteIdFlag = NoYes::No;
        parm.InventLocationIdFlag = !isAddItem;
        parm.WMSLocationIdFlag = NoYes::Yes;  
        if (!isAddItem)
        {
			parm.LicensePlateFlag = isLPItem;
        }
        //To or from basket?
        replaceLabels.insert(extendedTypeStr(WMSLocationId),isAddItem ? "@MobileWMS:MEL37" : "@MobileWMS:MEL44");
        TFMInventDimSetup inventDimSetup = TFMInventDimSetup::Construct(InventTable::find(itemId));
        returnMap = MobInventDimHelper::GetInventDimCollectors(add,inventDimSetup,parm,replaceLabels);
        add = returnMap.elements() *10 + 100;
        dictType = new SysDictType(extendedTypeNum(Qty));
        decimalPrecision = unitOfMeasure::findBySymbol(inventTable::find(itemId).inventUnitId()).DecimalPrecision;
        if (!decimalPrecision && !parm.InventSerialIdFlag && !inventDimParm.InventSerialIdFlag)
        {
            qtyStepMap = TFMRegistrationCollectorInteger::IntegerStepMap(add,'QuantityRemaining',"@SYS130676",dictType.label(),'',false,'',0,iSum ? real2int(iSum.PhysicalInvent) : 10000000,14);
        }
        else if (!parm.InventSerialIdFlag && !inventDimParm.InventSerialIdFlag)
        {
            qtyStepMap = TFMRegistrationCollectorDecimal::DecimalStepMap(add,'QuantityRemaining',"@SYS130676",dictType.label(),'',false,'',0,iSum ? real2int(iSum.PhysicalInvent) : 10000000,14);
        }
		if (qtyStepMap)
        {
			returnMap.insert(MobConstants::Quantity(),qtyStepMap);
        }
        return returnMap;
    }

[TFMCollectorMap(classStr(TFMGetRegistrationConfiguration), 'AddNewCart')]
public Map AddNewCartPrompt()
{
    Map returnMap = new Map(Types::string, Types::class);
    TFMRegistrationCollectorText locationId = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(wmsLocationId));
    TFMRegistrationCollectorText CartId = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(MobCartId));
    NumberSeq		num = NumberSeq::newGetNum(WHSParameters::numRefWHSLicensePlateId());

    locationId.parmId(3);      
    CartId.parmDefaultValue(num.num());
    cartid.parmLabel("@MobileWMS:CartID");
    num.used(); // mark the number as used
    returnMap.insert(locationId.parmName(),locationId.getMap());
    returnMap.insert(CartId.parmName(),CartId.getMap());
    return returnMap;
}

    [TFMCollectorMap(classStr(TFMGetRegistrationConfiguration), 'CartUnload')]
    public Map UnloadCartPrompt()
    {
        Map								returnMap = new Map(Types::string, Types::class);
        MobCartID						cartId = request.getFieldValue(extendedTypeStr(MobCartID));
        TFMRegistrationCollectorText	locationId = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(wmsLocationId));
        TFMRegistrationCollectorList	regCollectorList = new TFMRegistrationCollectorList(5,MobConstants::Warehouse(),"@SYS6437","@SYS6437","@SYS6437"); 
        TFMRegistrationCollectorText	licensePlateId = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WHSLicensePlateId));
        MobCarts						cart = MobCarts::Find(cartId);
        MobCartType						cartType = MobCartType::FindCartTypeSubClass(cart.ReferenceId);
        InventSum						iSum;
        InventDim						iDim;

        if (cartType!= null)
        {
            returnMap = cartType.UnloadCartPromptOverride(request);
            if (returnMap != null)
            {
                return returnMap;
            }
            returnMap = new Map(Types::string, Types::class);
        }


        regCollectorList.parmDataTable(methodStr(TFMGetReferenceData,WarehouseFilterList));
        regCollectorList.parmDataKeyColumn(extendedtypestr(InventLocationId));
        regCollectorList.parmDataDisplayColumn(extendedtypestr(Name));


        locationId.parmName(locationId.parmName()+'To');
        locationId.parmLabel("@SYS50351");
        locationId.parmHeader("@SYS50351");
        locationId.parmId(10);

        returnMap.insert(locationId.parmName(),locationId.getMap());

        returnMap.insert(regCollectorList.parmName(),regCollectorList.getMap());

        select firstonly iSum where iSum.PhysicalInvent
            join iDim where iDim.inventDimId == iSum.InventDimId && iDim.LicensePlateId == cart.WHSLicensePlateId;

        if (iSum && cart.WHSLicensePlateId)
        {
			//Items on the carts licenseplate. Ask for destination LP
            licensePlateId.parmId(15);
            licensePlateId.parmOptional(false);
            returnMap.insert(licensePlateId.parmName(),licensePlateId.getMap());
        }

        return returnMap;
    }

[TFMDocumentType(classStr(TFMPostAdhocRegistration), 'CartSwitchMode')]
public void postCartModeSwitch()
{
    MobCartId	CartId = request.getFieldValue(extendedTypeStr(MobCartID));        
    MobCarts	cart;
    MobCartType			cartType = MobCartType::FindCartTypeSubClass(MobCarts::Find(CartId).ReferenceId);

    if (cartType!= null && cartType.cartModePostOverride(request))
    {
        return;
    }

    ttsbegin;
    cart = MobCarts::Find(CartId,true);
    cart.PickMode = !cart.PickMode;
    cart.update();
    ttscommit;
    resultStr = "@MobileWMS:CartModeSwitched";
}

[TFMDocumentType(classStr(TFMPostAdhocRegistration), 'CartUnload')]
public void postCartUnload()
{

    wmsLocationId		Location = request.getFieldValue(extendedTypeStr(wmsLocationId) + 'To');
    InventLocationId	warehouseTo = request.getFieldValue(MobConstants::Warehouse());
    MobCartId			CartId = request.getFieldValue(extendedTypeStr(MobCartID));
    MobCarts			cart = MobCarts::Find(CartId);
    MobCartType			cartType = MobCartType::FindCartTypeSubClass(cart.ReferenceId);
    InventSum			iSum;
    InventDim			iDim;
    InventDim			iDimTo;
    WMSLocation			wmsLoc;
    Set					recordsToSkip = new Set(Types::Int64);

    if (cartType!= null && cartType.postCartUnloadOverride(request))            
    {
        return;
    }

    select firstonly iSum where iSum.PhysicalInvent
        join iDim where iDim.inventDimId == iSum.InventDimId && iDim.LicensePlateId == cart.WHSLicensePlateId;

    if (iSum && cart.WHSLicensePlateId)
    {
        wmsLoc = MobInventDimHelper::WmsLocationIdFromLicensePlate(request.getFieldValue(extendedTypeStr(WHSLicensePlateId)));
        //Items on the carts licenseplate. Ask for destination LP
        iDimTo.data(iDim);
        iDimTo.InventLocationId = wmsLoc.inventLocationId;
        iDimTo.wMSLocationId = wmsLoc.wMSLocationId;
        iDimTo.LicensePlateId = request.getFieldValue(extendedTypeStr(WHSLicensePlateId));
        MobPostHelper::inventJournalTransfer(iSum.PhysicalInvent,iSum.itemId,iDim, iDimTo);
        recordsToSkip.add(iSum.RecId);
    }

    MobPostHelper::MoveLocation(cart.InventLocationId,cart.WMSLocationId,location,warehouseTo, recordsToSkip);

    MobReservedCarts::unreserveCart(CartId);

    if (cartType!= null && cartType.postCartUnloadpostProcess(request))
    {
        return;
    }

    resultStr = "@MobileWMS:ContentMoved";
}

[TFMCollectorMap(classStr(TFMGetRegistrationConfiguration), 'CartChangeNote')]
public Map CartChangeNotePrompt()
{
    Map returnMap = new Map(Types::string, Types::class);        
    MobCartId CartId = request.getFieldValue(extendedTypeStr(MobCartID));
    TFMRegistrationCollectorText NoteCol = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(Notes));
    MobCarts	carts = MobCarts::Find(CartId);
    NoteCol.parmDefaultValue(carts.Note);
    NoteCol.parmLength(1000);
    NoteCol.parmprimaryInputMethod(TFMPrimaryInputMethod::Control);
    returnMap.insert(NoteCol.parmName(),NoteCol.getMap());
    return returnMap;
}

